package org.example.home;

/** Something in the home that can be switched on and off. */
public abstract class Device {
    private final String name;
    private boolean on;

    protected Device(String name) {
        if (name == null || name.isBlank()) {
            throw new IllegalArgumentException("a device needs a name");
        }
        this.name = name;
    }

    public String getName() {
        return name;
    }

    public boolean isOn() {
        return on;
    }

    public void turnOn() {
        on = true;
    }

    public void turnOff() {
        on = false;
    }

    /** A one-line description of the device's state, such as "Hall light: on at 60%". */
    public abstract String status();
}

package org.example.home;

/** A device whose level can be set from 0 to 100. */
public interface Dimmable {
    void setLevel(int level);

    int getLevel();

    /** Raises the level by amount, but never above 100. */
    default void brighten(int amount) {
        setLevel(Math.min(100, getLevel() + amount));
    }
}

package org.example.home;

/** Builds a small smart home and reports on it. Light, Thermostat and Reading are yours to write. */
public class SmartHome {
    public static void main(String[] args) {
        Light hall = new Light("Hall light");
        Light porch = new Light("Porch light");
        Light study = new Light("Study light");
        Thermostat lounge = new Thermostat("Lounge thermostat");

        hall.turnOn();
        hall.setLevel(60);
        porch.turnOn();
        porch.setLevel(30);
        porch.brighten(80);
        lounge.turnOn();
        lounge.setTarget(21.5);

        Device[] devices = {hall, porch, study, lounge};
        for (Device device : devices) {
            System.out.println(device.status());
        }

        Reading reading = new Reading(lounge.getName(), 19.5);
        System.out.println(reading);

        try {
            hall.setLevel(150);
        } catch (IllegalArgumentException e) {
            System.out.println("Rejected: " + e.getMessage());
        }
        try {
            lounge.setTarget(45);
        } catch (IllegalArgumentException e) {
            System.out.println("Rejected: " + e.getMessage());
        }
        try {
            new Reading(" ", 20);
        } catch (IllegalArgumentException e) {
            System.out.println("Rejected: " + e.getMessage());
        }
    }
}

