package org.example.password;

import java.util.ArrayList;
import java.util.List;

/** Checks passwords against a simple policy. */
public class PasswordChecker {

    public static final int MIN_LENGTH = 10;

    /** Returns the rules the password breaks, in a fixed order; an empty list means it's acceptable. */
    public List<String> problems(String password) {
        if (password == null) {
            throw new IllegalArgumentException("password is null");
        }
        List<String> problems = new ArrayList<>();
        if (password.length() <= MIN_LENGTH) {
            problems.add("at least " + MIN_LENGTH + " characters");
        }
        if (!containsDigit(password)) {
            problems.add("a digit");
        }
        if (!containsUpperCase(password)) {
            problems.add("an upper-case letter");
        }
        if (password.contains(" ")) {
            problems.add("no spaces");
        }
        return problems;
    }

    /** "weak" if the password breaks a rule, "strong" if it's acceptable and at least 14 characters long, otherwise "ok". */
    public String strength(String password) {
        if (!problems(password).isEmpty()) {
            return "weak";
        }
        return password.length() >= 14 ? "strong" : "ok";
    }

    private boolean containsDigit(String s) {
        for (char c : s.toCharArray()) {
            if (Character.isDigit(c)) {
                return true;
            }
        }
        return false;
    }

    private boolean containsUpperCase(String s) {
        for (int i = 1; i < s.length(); i++) {
            if (Character.isUpperCase(s.charAt(i))) {
                return true;
            }
        }
        return false;
    }
}

package org.example.password;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import java.util.List;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

class PasswordCheckerTest {

    private PasswordChecker checker;

    @BeforeEach
    void setUp() {
        checker = new PasswordChecker();
    }

    @Test
    void acceptsAGoodPassword() {
        assertEquals(List.of(), checker.problems("Rainy7Days!x"));
    }

    @Test
    void reportsAMissingDigit() {
        assertEquals(List.of("a digit"), checker.problems("NoDigitsHere"));
    }

    @Test
    void rejectsNull() {
        assertThrows(IllegalArgumentException.class, () -> checker.problems(null));
